mapper.select:
SELECT aa.USER_ID AS userId, uc.LOGIN_ID AS loginId, u.NICKNAME AS nickname, u.NAME AS name, aa.APPROVAL_STATUS AS approvalStatus, aa.ADMIN_GRADE AS adminGrade, aa.CREATED_AT AS createdAt, COUNT(*) OVER() AS totalCount FROM ADMIN_ACCOUNT aa JOIN USERS u ON u.USER_ID = aa.USER_ID JOIN USER_CREDENTIAL uc ON uc.USER_ID = aa.USER_ID WHERE u.DELETED_YN = 'N'
AND aa.APPROVAL_STATUS = #{approvalStatus}
ORDER BY aa.CREATED_AT DESC LIMIT #{pagination.size} OFFSET #{pagination.offset}

mapper.update:
UPDATE USER_ROLES
SET ROLE = #{role},
    UPDATED_AT = NOW(),
    UPDATED_BY = #{approvedBy}
WHERE USER_ID = #{userId}
  AND ROLE = 'ROLE_ADMIN_PENDING'
